  [inst_4 : Countable T] [inst_5 : MeasurableSingletonClass T] [inst_6 : Countable T']
  [inst_7 : MeasurableSingletonClass T'] [inst_8 : MeasurableSingletonClass G] [inst_9 : Countable G] {κ : Kernel T G}
  {η : Kernel T' G} [inst_10 : IsMarkovKernel κ] [inst_11 : IsMarkovKernel η] {μ : Measure T} {ν : Measure T'}
  [inst_12 : IsProbabilityMeasure μ] [inst_13 : IsProbabilityMeasure ν] [inst_14 : FiniteSupport μ]
