theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_2, u_1} {T : Type u_1} {T' : Type u_2} {G : Type u_4}
  [inst : MeasurableSpace T] [inst_1 : MeasurableSpace T'] [inst_2 : MeasurableSpace G] [inst_3 : AddCommGroup G]
  [inst_4 : Countable T] [inst_5 : MeasurableSingletonClass T] [inst_6 : Countable T']
  [inst_7 : MeasurableSingletonClass T'] [inst_8 : MeasurableSingletonClass G] [inst_9 : Countable G] {κ : Kernel T G}
  {η : Kernel T' G} [inst_10 : IsMarkovKernel κ] [inst_11 : IsMarkovKernel η] {μ : Measure T} {ν : Measure T'}
  [inst_12 : IsProbabilityMeasure μ] [inst_13 : IsProbabilityMeasure ν] [inst_14 : FiniteSupport μ]
  [inst_15 : FiniteSupport ν] (hκ : κ.AEFiniteKernelSupport μ) (hη : η.AEFiniteKernelSupport ν)
  (h : Hk[κ , μ] ⊔ Hk[η , ν] ≤ Hk[(prodMkRight T' κ ×ₖ prodMkLeft T η).map fun p => p.1 - p.2 , μ.prod ν]) :
  -(2 * (Hk[(prodMkRight T' κ ×ₖ prodMkLeft T η).map fun x => x.1 - x.2 , μ.prod ν] - Hk[κ , μ] / 2 - Hk[η , ν] / 2)) ≤
    Hk[κ , μ] - Hk[η , ν] := sorry

theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_2, u_1} {T : Type u_1} {T' : Type u_2} {G : Type u_4}
  [inst : MeasurableSpace T] [inst_1 : MeasurableSpace T'] [inst_2 : MeasurableSpace G] [inst_3 : AddCommGroup G]
  [inst_4 : Countable T] [inst_5 : MeasurableSingletonClass T] [inst_6 : Countable T']
  [inst_7 : MeasurableSingletonClass T'] [inst_8 : MeasurableSingletonClass G] [inst_9 : Countable G] {κ : Kernel T G}
  {η : Kernel T' G} [inst_10 : IsFiniteKernel κ] [inst_11 : IsFiniteKernel η] {μ : Measure T} {ν : Measure T'}
  [inst_12 : IsProbabilityMeasure μ] [inst_13 : IsProbabilityMeasure ν] [inst_14 : FiniteSupport μ]
  [inst_15 : FiniteSupport ν] :
  Hk[(prodMkRight T' κ ×ₖ prodMkLeft T η).map fun x => x.1 - x.2 , μ.prod ν] - (Hk[η , ν] / 2 + Hk[κ , μ] / 2) =
    Hk[(prodMkRight T η ×ₖ prodMkLeft T' κ).map fun x => x.1 - x.2 , ν.prod μ] -
      (Hk[η , ν] / 2 + Hk[κ , μ] / 2) := sorry
